INSERT INTO public.question (id, course_id, rubric_id, generation_id, topic, prompt, expected_answer, source_ref, key_points, bloom_level, status, source, author_id, reviewed_by, reviewed_at, created_at, updated_at) VALUES
	('e0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'Architecture styles', 'Compare layered architecture with microservices.', 'Layered is simpler to build and deploy as one unit. Microservices scale and deploy independently but add operational and network complexity.', NULL, 'monolith vs distributed, independent deployment, complexity trade-off', 'ANALYZE', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'SOLID', 'What does the Dependency Inversion Principle say?', 'High-level modules should not depend on low-level modules. Both should depend on abstractions.', NULL, 'abstractions, high-level vs low-level, decoupling', 'REMEMBER', 'PENDING_REVIEW', 'AI', 'a0000000-0000-0000-0000-000000000002', NULL, NULL, '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'Normalization', 'Why do we normalize a database to third normal form?', 'To reduce redundancy and avoid update, insert and delete anomalies by removing partial and transitive dependencies.', NULL, 'redundancy, anomalies, transitive dependency', 'UNDERSTAND', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'SQL', 'When would you choose a LEFT JOIN instead of an INNER JOIN?', 'Use LEFT JOIN when rows from the left table must be kept even without a match in the right table.', NULL, 'keep unmatched rows, null values, reporting', 'APPLY', 'APPROVED', 'IMPORT', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'MVC', 'Trong mô hình MVC, vai trò của Controller là gì?', 'Controller nhận input từ người dùng, gọi Model xử lý dữ liệu và chọn View để hiển thị kết quả.', NULL, 'điều phối luồng, tách biệt giao diện và logic', 'REMEMBER', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'Clean architecture', 'So sánh Clean Architecture với kiến trúc phân lớp truyền thống khi dự án cần mở rộng theo domain.', 'Clean Architecture đặt business rules ở trung tâm và phụ thuộc hướng vào trong; phân lớp truyền thống dễ bị ràng buộc chặt giữa UI, service và persistence.', NULL, 'dependency rule, domain ở core, đổi UI/DB ít ảnh hưởng logic', 'ANALYZE', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'SOLID', 'Cho ví dụ cách áp dụng Open/Closed Principle khi thêm loại báo cáo mới.', 'Định nghĩa interface ReportExporter và thêm implementation mới thay vì sửa class cũ đang xử lý nhiều định dạng.', NULL, 'interface, mở rộng không sửa code cũ, strategy', 'APPLY', 'PENDING_REVIEW', 'AI', 'a0000000-0000-0000-0000-000000000002', NULL, NULL, '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'Indexing', 'Khi nào nên tạo composite index và thứ tự cột trong index có ý nghĩa gì?', 'Dùng composite index khi truy vấn lọc/sắp xếp theo nhiều cột; cột có độ chọn lọc cao hoặc xuất hiện trong WHERE nên đứng trước.', NULL, 'leftmost prefix, selectivity, covering index', 'APPLY', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'Transactions', 'Giải thích bốn thuộc tính ACID của giao dịch cơ sở dữ liệu.', 'Atomicity (all-or-nothing), Consistency (ràng buộc được giữ), Isolation (giao dịch không thấy trạng thái trung gian của nhau), Durability (commit tồn tại sau sự cố).', NULL, 'atomic, consistent, isolated, durable', 'REMEMBER', 'PENDING_REVIEW', 'IMPORT', 'a0000000-0000-0000-0000-000000000002', '61489f13-bfad-4a5d-8699-2fea4413c52a', '2026-10-06 04:49:05.00482+00', '2026-10-05 12:18:27.149038+00', '2026-10-06 04:49:05.00482+00'),
	('e0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'Design patterns', 'Explain the Singleton pattern and one risk of using it.', 'Singleton ensures a class has a single instance with a global access point. Risks include hidden global state and harder unit testing.', NULL, 'single instance, global access point, hidden state, testing difficulty', 'UNDERSTAND', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-06 05:49:16.994211+00', '2026-10-05 12:18:27.149038+00', '2026-10-06 05:49:16.994211+00'),
	('76bbdbeb-ee3f-4ae1-9400-338a9c129dd0', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', '1c09a07f-fee3-44f9-ba2d-c381a9f0ed65', 'SQL joins', 'What does a SQL JOIN combine rows from?', NULL, 'aives-db.docx, page 1', NULL, 'REMEMBER', 'PENDING_REVIEW', 'AI', 'a0000000-0000-0000-0000-000000000002', NULL, NULL, '2026-10-06 07:56:37.755694+00', '2026-10-06 07:56:37.755694+00'),
	('416063fc-dffe-4b08-8f82-fbad3f389eb0', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'If a device cannot access the internet, outline the troubleshooting steps you would follow, referencing the definitions of IP configuration, gateway, DNS, and the use of ping.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.566622+00', '2026-10-06 07:58:13.384497+00', '2026-10-06 07:58:34.566622+00'),
	('ba401e48-91b8-490e-9a73-0c4a6a62e8cd', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Describe the process a browser follows to load a website when you type "example.com" into the address bar, incorporating the definitions of DNS, HTTP/HTTPS, and the steps outlined in the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.729026+00', '2026-10-06 07:58:13.379763+00', '2026-10-06 07:58:34.729026+00'),
	('77d1b3ff-c7a6-4778-8b02-13dec3b1f424', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'A server is configured to listen on port 443. Using the definitions of port numbers and HTTP/HTTPS, explain which protocol is likely being used and why.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.868979+00', '2026-10-06 07:58:13.375137+00', '2026-10-06 07:58:34.868979+00'),
	('a6359095-2062-492d-8698-20fe4240977f', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Compare and contrast the functions of a hub and a switch, and explain why a switch is typically preferred in modern LANs, based on the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:35.004721+00', '2026-10-06 07:58:13.370188+00', '2026-10-06 07:58:35.004721+00'),
	('8a58d901-9def-4532-99b5-2a5b1a953959', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'A network uses a default gateway of 192.168.1.1. Explain what happens when a host sends traffic to a destination outside its local network, using the definition of default gateway.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:35.165631+00', '2026-10-06 07:58:13.36362+00', '2026-10-06 07:58:35.165631+00'),
	('8ec75bfd-c032-4725-9416-6c8317f723d7', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'If a packet is lost during transmission, describe the steps you would take to troubleshoot the issue, referencing the definitions of packet loss and ping.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:35.320245+00', '2026-10-06 07:58:13.358718+00', '2026-10-06 07:58:35.320245+00'),
	('dd12842e-36a1-43dc-acbd-d6e244bbc6a9', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Given a device with IP address 10.0.0.5 and subnet mask 255.0.0.0, determine the network address and the range of host addresses using the definitions of subnet mask and IP address from the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:35.480119+00', '2026-10-06 07:58:13.352471+00', '2026-10-06 07:58:35.480119+00'),
	('924b5365-8e11-4a05-995f-c5acbcd55a87', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Explain the difference between TCP and UDP and provide a scenario where each protocol would be the appropriate choice, based on the definitions provided.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:32.519197+00', '2026-10-06 07:58:13.399223+00', '2026-10-06 07:58:32.519197+00'),
	('4c7628c5-036c-459a-8f34-98396a031306', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Given a network with high latency, explain how this impacts real-time applications such as VoIP, using the definition of latency.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.272471+00', '2026-10-06 07:58:13.393053+00', '2026-10-06 07:58:34.272471+00'),
	('e7e7d28b-1146-48fd-a145-bd8dbc6779cb', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Explain how NAT allows multiple devices in a private network to share a single public IP address, using the definition of NAT from the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.427185+00', '2026-10-06 07:58:13.388795+00', '2026-10-06 07:58:34.427185+00'),
	('1d3aad37-036d-459f-b7d0-82b59a76be52', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'Compare the WHERE and HAVING clauses in SQL with respect to when they are applied during query execution and the types of functions they can contain.', 'WHERE filters individual rows before any GROUP BY operation and cannot contain aggregate functions such as SUM, AVG, COUNT, MAX, MIN. HAVING filters groups after the GROUP BY has been performed and is typically used with aggregate functions.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'WHERE filters rows before GROUP BY; WHERE cannot contain aggregate functions; HAVING filters groups after GROUP BY; HAVING often contains aggregate functions', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:35:59.246716+00', '2026-10-06 08:35:33.429355+00', '2026-10-06 08:35:59.246716+00'),
	('e8d8147f-4de1-4dd4-b67e-e17e49bbef36', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'Analyze the trade‑offs of creating an index on a table: explain the performance benefits for read operations and the penalties for write operations.', 'An index (usually B‑Tree or Hash) speeds up data retrieval for WHERE, JOIN, and ORDER BY clauses by avoiding full table scans. However, it consumes extra disk/memory space and slows down INSERT, UPDATE, and DELETE operations because the index structure must be updated on each write.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'Index speeds up SELECT/WHERE/JOIN/ORDER BY; Index avoids full table scan; Index consumes extra storage; Index slows INSERT/UPDATE/DELETE due to maintenance', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:00.768478+00', '2026-10-06 08:35:33.439535+00', '2026-10-06 08:36:00.768478+00'),
	('863111f9-5339-458b-a8bc-2ff263b24c28', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'A table uses a composite primary key. Explain why achieving Second Normal Form (2NF) is necessary and describe the specific anomaly it eliminates.', '2NF requires the table to be in 1NF and that every non‑key attribute be fully functionally dependent on the entire primary key, not just part of it. This removes partial dependency anomalies where a non‑key attribute depends on only a portion of the composite key, leading to redundancy and update anomalies.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', '2NF requires 1NF; non‑key attributes must depend on whole primary key; eliminates partial dependency; prevents redundancy and update anomalies', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:02.052424+00', '2026-10-06 08:35:33.447562+00', '2026-10-06 08:36:02.052424+00'),
	('b3ff5603-c428-4dfe-8bf2-01789c80f6ba', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'Contrast the scaling approaches of relational (SQL) and non‑relational (NoSQL) databases and relate these approaches to their typical ACID compliance.', 'Relational databases use a fixed schema, enforce strong ACID properties, and scale vertically by adding more powerful hardware. NoSQL databases use flexible schemas (document, key‑value, graph, wide‑column), often relax strict ACID for higher performance, and scale horizontally by adding more nodes.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'SQL: fixed schema, strong ACID, vertical scaling; NoSQL: flexible schema, relaxed ACID, horizontal scaling; SQL examples: MySQL, Oracle, SQL Server; NoSQL examples: MongoDB, Redis, Cassandra, Neo4j', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:03.563347+00', '2026-10-06 08:35:33.453743+00', '2026-10-06 08:36:03.563347+00'),
	('ff89ae4c-6007-437a-aca7-4264971b8f27', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'A funds‑transfer transaction debits one account and credits another. Describe how each ACID property (Atomicity, Consistency, Isolation, Durability) protects the database if a crash occurs after the debit but before the credit.', 'Atomicity ensures the whole transfer either completes fully or is rolled back, so the debit alone cannot persist. Consistency guarantees the database moves from one valid state (balanced accounts) to another. Isolation prevents other concurrent transactions from seeing the intermediate debit‑only state. Durability ensures that once the transaction commits, both debit and credit survive any subsequent system failure.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'Atomicity: all‑or‑nothing; Consistency: valid state to valid state; Isolation: concurrent transactions do not interfere; Durability: committed data persists after crash', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:05.870397+00', '2026-10-06 08:35:33.460373+00', '2026-10-06 08:36:05.870397+00');
ON CONFLICT DO NOTHING;
