INSERT INTO public.answer (id, turn_id, status, transcript, stt_confidence, duration_ms, needs_follow_up, follow_up_reason, stt_latency_ms, llm_latency_ms, answered_at) VALUES
	('92000000-0000-0000-0000-000000000001', '91000000-0000-0000-0000-000000000001', 'ANSWERED', 'Singleton keeps only one instance of a class and gives a global access point. The risk is that it hides global state.', 0.940, 21000, true, 'MISSING_POINT', NULL, NULL, '2026-10-05 12:18:27.167072+00'),
	('92000000-0000-0000-0000-000000000002', '91000000-0000-0000-0000-000000000002', 'ANSWERED', 'I would inject the instance through an interface so a test can replace it with a fake.', 0.910, 14000, false, NULL, NULL, NULL, '2026-10-05 12:18:27.167072+00');
