INSERT INTO public.knowledge_chunk (id, course_id, document_id, topic, title, source_label, chunk_index, content, embedding, created_at) VALUES
	('8e369535-7ca5-4007-bb02-001970953cc8', '29c39f28-4606-47fd-b66c-4a72db569105', '13e5f36e-7cad-4f46-9fe9-624473ab5a58', '50_software_engineering_questions', '50_software_engineering_questions.docx', 'page 1', 0, '50 Software Engineering Questions
Question bank for study, discussion, and oral examination
Instructions: Answer each question in your own words. Use examples where appropriate. Questions cover fundamentals, requirements, process models, design, testing, DevOps, security, and maintenance.
Fundamentals
1. What is software engineering, and how does it differ from programming?
SDLC
2. What are the main activities in a typical software development life cycle (SDLC)?
Requirements
3. What is the difference between functional and non-functional requirements?
4. Why is requirements elicitation important in a software project?
5. What is a Software Requirements Specification (SRS), and what should it contain?
6. How can ambiguous requirements affect software quality and project cost?
Quality
7. What is the difference between verification and validation?
